cat > C:/Users/User1/AppData/Local/Temp/claude/C--Users-User1-Desktop-dark-raiders/8a09e991-b4f4-4b23-b10f-ded92e837fc3/scratchpad/mk-cw-steadyframe.ps1 <<'EOF'
$g=[IO.File]::ReadAllText($(if($env:MK_SRC){$env:MK_SRC}else{'C:\claudecode\dark raiders\dark_raiders.html'}))
function L([string]$rx){ $m=[regex]::Matches($g,$rx); if($m.Count -ne 1){ throw "anchor $rx matched $($m.Count)" }; return $m[0].Value.Replace("`r",'') }
$a1=L "if\(state==='raid'&&G&&!G\.over&&!G\.sim&&!HID\.fromWorker&&!document\.hidden&&DRS\.frameStart!==undefined\)\{"
$r1="if(dt>0&&state==='raid'&&G&&!G.over&&!G.sim&&!HID.fromWorker&&!document.hidden&&DRS.frameStart!==undefined){   // v28.xx (cw-steadyframe): a frozen redraw (dt 0) is not a real frame, so it never feeds the auto resolution window; on a slow PC its stale frame gap pushed the scale down between two redraws and the picture changed"
$chk=@'
  {v:'VER',what:'a frozen redraw (dt 0) does not feed the auto resolution window, so two redraws of a frozen frame stay identical on a slow PC',
   run:function(){
     if(typeof DRS==='undefined'||typeof drsTick!=='function') return 'SKIP: no auto resolution';
     __forceSize(1920,1080); __resetCfg(); __pinDefaults(0);
     __deploy({kit:[],safe:null,mapIx:0,seed:4242});
     for(var f=0;f<3;f++) __loop(performance.now()+f*16.7);
     if(document.hidden) return 'SKIP: page hidden, the auto resolution does not tick';
     DRS.win=[]; DRS.slowT=0; DRS.fastT=0; DRS.frameGap=40; DRS.frameStart=performance.now();
     for(f=0;f<8;f++) __frame(0);
     var n=DRS.win?DRS.win.length:0;
     if(n||DRS.slowT>0) return 'frozen redraws fed the auto resolution window ('+n+' samples, slow time '+DRS.slowT.toFixed(0)+')';
     return null; }},
'@.Replace("`r",'')
$d=[ordered]@{
  title='FROZEN REDRAW STAYS STEADY'
  why='Two spare PC checks (9.07, 33.51) failed only on the slow machine: a redraw of a frozen frame fed the auto resolution window with a stale frame gap, so the scale could move between two redraws. Redraws with no clock step no longer steer quality.'
  now='A redraw that does not advance the clock never changes the auto resolution.'
  edits=@( [ordered]@{ anchor=$a1; replacement=$r1 } )
  check=$chk
}
[IO.File]::WriteAllText('C:\claudecode\dark raiders\tools\handoff\drafts\draft-cw-steadyframe.json',($d | ConvertTo-Json -Depth 6),(New-Object Text.UTF8Encoding $false))
'written'
EOF
